#!/usr/bin/env bash
set -euo pipefail

# Generated public installer. Obtain its SHA-256 and the release key fingerprint
# through an independent trusted channel before running it as root.
version=''
key_sha256=''
verify_only=0
asset_dir=''
offline_install=0
upgrade=0
domain=''
email=''
admin_email=''
tls_cert=''
tls_key=''
restore_archive=''
backup_metadata=''
backup_signing_key=''
backup_identity=''
while (($#)); do
  case "$1" in
    --upgrade) upgrade=1; shift ;;
    --restore-backup) restore_archive="${2:-}"; shift 2 ;;
    --backup-metadata) backup_metadata="${2:-}"; shift 2 ;;
    --backup-signing-key) backup_signing_key="${2:-}"; shift 2 ;;
    --backup-identity) backup_identity="${2:-}"; shift 2 ;;
    --update-status|--recover)
      [[ $(id -u) = 0 && -f /usr/local/lib/qros/update-native.py ]] || exit 77
      operation="${1#--}"; [[ "$operation" != update-status ]] || operation=status
      shift
      exec python3 -B /usr/local/lib/qros/update-native.py "$operation" "$@" ;;
    --version) version="${2:-}"; shift 2 ;;
    --key-sha256) key_sha256="${2:-}"; shift 2 ;;
    --verify-only) verify_only=1; shift ;;
    --asset-dir) asset_dir="${2:-}"; shift 2 ;;
    --offline-install) offline_install=1; shift ;;
    --domain) domain="${2:-}"; shift 2 ;;
    --email) email="${2:-}"; shift 2 ;;
    --admin-email) admin_email="${2:-}"; shift 2 ;;
    --tls-cert) tls_cert="${2:-}"; shift 2 ;;
    --tls-key) tls_key="${2:-}"; shift 2 ;;
    --status|--check)
      [[ $# -eq 1 && -x /usr/local/sbin/qrosctl ]] || { echo 'QrOS is not installed or arguments conflict.' >&2; exit 64; }
      exec /usr/local/sbin/qrosctl "$1" ;;
    *) echo 'Unknown installer argument' >&2; exit 64 ;;
  esac
done
if [[ ! "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || [[ ! "$key_sha256" =~ ^[0-9a-f]{64}$ ]]; then
  echo 'Use --version X.Y.Z --key-sha256 64_HEX [--verify-only]' >&2
  exit 64
fi
if [[ -n "$asset_dir" && "$verify_only" -ne 1 && "$offline_install" -ne 1 ]]; then
  echo '--asset-dir requires --verify-only or explicit --offline-install' >&2
  exit 64
fi
if ((offline_install)) && [[ -z "$asset_dir" ]]; then
  echo '--offline-install requires --asset-dir containing signed release assets' >&2; exit 64
fi
if [[ -n "$restore_archive$backup_metadata$backup_signing_key$backup_identity" ]]; then
  [[ -n "$restore_archive" && -n "$backup_metadata" && -n "$backup_signing_key" && -n "$backup_identity" && "$upgrade" = 0 ]] || { echo 'Restore requires all four backup trust arguments and cannot be an upgrade.' >&2; exit 64; }
  [[ -z "$domain$email$admin_email$tls_cert$tls_key" ]] || { echo 'Restore uses authenticated backup configuration; overrides are not accepted.' >&2; exit 64; }
fi
if (( ! verify_only && ! upgrade )) && [[ -z "$restore_archive" && -z "$domain" ]]; then
  echo 'Installation requires --domain FQDN.' >&2; exit 64
fi
for command in curl openssl python3 tar sha256sum base64; do
  command -v "$command" >/dev/null || { echo "Missing installer tool: $command" >&2; exit 69; }
done
if [[ "$(uname -s)" != Linux || "$(uname -m)" != x86_64 ]]; then
  echo 'Only Linux amd64 is supported by this candidate' >&2
  exit 69
fi

temporary=$(mktemp -d /tmp/qros-install-XXXXXXXX)
trap 'if [[ -n "$temporary" && "$temporary" == /tmp/qros-install-* ]]; then rm -r -- "$temporary"; fi' EXIT
chmod 700 "$temporary"
printf '%s' '' | base64 -d > "$temporary/verify-package.py"
chmod 600 "$temporary/verify-package.py"
release_url="https://github.com/adrianomedina-amssoft/qros-amssoft/releases/download/v${version}"
key_url="${release_url}/release-public.pem"
fetch() {
  curl --proto '=https' --proto-redir '=https' --tlsv1.2 --fail --silent --show-error --location --retry 3 --max-time 180 --output "$2" "$1"
}
if [[ -n "$asset_dir" ]]; then
  [[ -d "$asset_dir" ]] || { echo 'Asset directory does not exist' >&2; exit 66; }
  cp -- "$asset_dir/release-public.pem" "$temporary/release-public.pem"
else
  fetch "$key_url" "$temporary/release-public.pem"
fi
actual_key_sha256=$(sha256sum "$temporary/release-public.pem")
if [[ "${actual_key_sha256%% *}" != "$key_sha256" ]]; then
  echo 'Release key differs from the independently supplied fingerprint' >&2
  exit 65
fi
if [[ -n "$asset_dir" ]]; then
  cp -- "$asset_dir/manifest.json" "$temporary/manifest.json"
  cp -- "$asset_dir/manifest.json.sig" "$temporary/manifest.json.sig"
else
  fetch "$release_url/manifest.json" "$temporary/manifest.json"
  fetch "$release_url/manifest.json.sig" "$temporary/manifest.json.sig"
fi
if ! openssl pkeyutl -verify -pubin -inkey "$temporary/release-public.pem" -rawin \
  -in "$temporary/manifest.json" -sigfile "$temporary/manifest.json.sig" >/dev/null 2>&1; then
  echo 'Manifest signature verification failed' >&2
  exit 65
fi
archive="$temporary/qros-${version}-linux-amd64.tar.gz"
if [[ -n "$asset_dir" ]]; then
  cp -- "$asset_dir/$(basename "$archive")" "$archive"
else
  fetch "$release_url/$(basename "$archive")" "$archive"
fi
python3 "$temporary/verify-package.py" \
  --manifest "$temporary/manifest.json" \
  --signature "$temporary/manifest.json.sig" \
  --public-key "$temporary/release-public.pem" \
  --key-sha256 "$key_sha256" \
  --archive "$archive" \
  --require-installable
if ((verify_only)); then
  echo 'Release verified; no installation was performed.'
  exit 0
fi

# The bootstrap is shipped inside the signed tar, then executed only after
# signature, digest, allowlist and internal inventory checks have passed.
if [[ "$(id -u)" -ne 0 ]]; then
  echo 'Installation requires root; verification does not.' >&2
  exit 77
fi
source /etc/os-release
if [[ "${ID:-}" != debian || "${VERSION_ID:-}" != 12 ]]; then
  echo 'Installation currently requires Debian 12' >&2
  exit 69
fi
mkdir "$temporary/stage"
tar -xzf "$archive" -C "$temporary/stage" --no-same-owner --no-same-permissions
if [[ ! -f "$temporary/stage/bootstrap.sh" ]]; then
  echo 'Release is missing its signed bootstrap; installation stopped.' >&2
  exit 78
fi
if [[ -n "$restore_archive$backup_metadata$backup_signing_key$backup_identity" ]]; then
  [[ -n "$restore_archive" && -n "$backup_metadata" && -n "$backup_signing_key" && -n "$backup_identity" && "$upgrade" = 0 ]] || exit 64
  [[ -z "$domain$email$admin_email$tls_cert$tls_key" ]] || exit 64
  python3 -B "$temporary/stage/host/native-backup.py" restore --archive "$restore_archive" --metadata "$backup_metadata" --signature-key "$backup_signing_key" --identity "$backup_identity" --bundle "$temporary/stage" --manifest "$temporary/manifest.json"
  exit $?
fi
if ((upgrade)); then
  [[ -f "$temporary/stage/host/update-native.py" && -f "$temporary/stage/host/recovery-guard.py" ]] || { echo 'Release lacks audited update components.' >&2; exit 78; }
  [[ -z "$domain$email$admin_email$tls_cert$tls_key" ]] || { echo 'Update preserves existing configuration; installation overrides are not accepted.' >&2; exit 64; }
  python3 -B "$temporary/stage/host/update-native.py" update --bundle "$temporary/stage" --manifest "$temporary/manifest.json"
  exit $?
fi
/bin/bash "$temporary/stage/bootstrap.sh" --bundle "$temporary/stage" --manifest "$temporary/manifest.json" \
  --domain "$domain" --email "$email" --admin-email "$admin_email" --tls-cert "$tls_cert" --tls-key "$tls_key"
